function drawBulbasaurFlowerBud(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.1;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 2.5;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 28 * (1.0 - 0.15 * breathSin), 7, 0, 0, Math.PI * 2); ctx.fill();

  // Hạt nụ xanh trên lưng
  ctx.fillStyle = '#22c55e';
  ctx.beginPath(); ctx.ellipse(6, by - 10, 14, 20, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#4ade80';
  ctx.beginPath(); ctx.moveTo(0, by - 24); ctx.lineTo(16, by - 36); ctx.lineTo(18, by - 18); ctx.fill();

  // Thân & chân
  ctx.fillStyle = '#2dd4bf';
  ctx.beginPath(); ctx.ellipse(-4, by + 14, 20 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-20, by + 24, 9, 12, 4); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-9,  by + 24, 9, 12, 4); ctx.fill();
  ctx.beginPath(); ctx.roundRect(4,   by + 24, 9, 12, 4); ctx.fill();
  ctx.beginPath(); ctx.roundRect(14,  by + 24, 9, 12, 4); ctx.fill();

  // Đầu
  ctx.beginPath(); ctx.ellipse(-6, by - 8, 20 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Tai
  ctx.beginPath(); ctx.moveTo(-20, by - 18); ctx.lineTo(-26, by - 32); ctx.lineTo(-12, by - 20); ctx.fill();
  ctx.beginPath(); ctx.moveTo(0,   by - 20); ctx.lineTo(6,   by - 32); ctx.lineTo(12,  by - 18); ctx.fill();

  // Đốm xanh
  ctx.fillStyle = '#0f766e';
  ctx.beginPath(); ctx.moveTo(-10, by - 18); ctx.lineTo(-6, by - 24); ctx.lineTo(-2, by - 18); ctx.fill();

  // Mắt đỏ
  if (!blink) {
    ctx.fillStyle = '#ef4444';
    ctx.beginPath(); ctx.moveTo(-16, by - 14); ctx.lineTo(-6, by - 14); ctx.lineTo(-14, by - 2); ctx.fill();
    ctx.beginPath(); ctx.moveTo(2,   by - 14); ctx.lineTo(12, by - 14); ctx.lineTo(4,   by - 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-11, by - 11, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(7,   by - 11, 2, 0, Math.PI * 2); ctx.fill();
  }

  // Miệng & răng
  ctx.fillStyle = '#881337';
  ctx.beginPath(); ctx.moveTo(-6, by + 6); ctx.lineTo(-14, by + 1); ctx.lineTo(2, by + 1); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(-12, by + 1, 2, 2);
  ctx.fillRect(0,   by + 1, 2, 2);

  ctx.restore();
}
